DROP TABLE IF EXISTS "public"."ImportBatch";
DROP TABLE IF EXISTS "public"."Assessment";
DROP TABLE IF EXISTS "public"."Category";
DROP TABLE IF EXISTS "public"."Question";
DROP TABLE IF EXISTS "public"."QuestionOption";
DROP TABLE IF EXISTS "public"."AssessmentQuestion";
DROP TABLE IF EXISTS "public"."UserBatch";
DROP TABLE IF EXISTS "public"."AssessmentAnswer";
DROP TABLE IF EXISTS "public"."User";
DROP TABLE IF EXISTS "public"."ExamControl";
DROP TABLE IF EXISTS "public"."AwsMarketplaceSubscription";
DROP TABLE IF EXISTS "public"."AwsMarketplaceEvent";
-- Sequence and defined type
DROP TYPE IF EXISTS "public"."AssessmentStatus";
CREATE TYPE "public"."AssessmentStatus" AS ENUM ('IN_PROGRESS', 'COMPLETED');
DROP TYPE IF EXISTS "public"."Difficulty";
CREATE TYPE "public"."Difficulty" AS ENUM ('EASY', 'MEDIUM', 'HARD');
DROP TYPE IF EXISTS "public"."Role";
CREATE TYPE "public"."Role" AS ENUM ('SUPER_ADMIN', 'ADMIN', 'USER');
DROP TYPE IF EXISTS "public"."AwsSubscriptionStatus";
CREATE TYPE "public"."AwsSubscriptionStatus" AS ENUM ('PENDING_REGISTRATION', 'SUBSCRIBED', 'SUSPENDED', 'UNSUBSCRIBED', 'PENDING_EVENT');

-- Table Definition
CREATE TABLE "public"."ImportBatch" (
    "id" text NOT NULL,
    "fileName" text NOT NULL,
    "fileType" text NOT NULL,
    "totalQuestions" int4 NOT NULL,
    "validQuestions" int4 NOT NULL,
    "invalidQuestions" int4 NOT NULL,
    "importedQuestions" int4 NOT NULL,
    "uploadedBy" text NOT NULL,
    "createdById" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."Assessment" (
    "id" text NOT NULL,
    "userId" text NOT NULL,
    "status" "public"."AssessmentStatus" NOT NULL DEFAULT 'IN_PROGRESS'::"AssessmentStatus",
    "totalQuestions" int4 NOT NULL DEFAULT 50,
    "attemptedQuestions" int4 NOT NULL DEFAULT 0,
    "correctAnswers" int4 NOT NULL DEFAULT 0,
    "incorrectAnswers" int4 NOT NULL DEFAULT 0,
    "unanswered" int4 NOT NULL DEFAULT 50,
    "score" float8 NOT NULL DEFAULT 0,
    "percentage" float8 NOT NULL DEFAULT 0,
    "startedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "durationMinutes" int4 NOT NULL DEFAULT 60,
    "deadlineAt" timestamp(3),
    "submittedAt" timestamp(3),
    "submissionReason" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."Category" (
    "id" text NOT NULL,
    "name" text NOT NULL,
    "questionQuantity" int4 NOT NULL DEFAULT 0,
    "createdById" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."Question" (
    "id" text NOT NULL,
    "questionText" text NOT NULL,
    "categoryId" text,
    "difficulty" "public"."Difficulty" NOT NULL DEFAULT 'MEDIUM'::"Difficulty",
    "isActive" bool NOT NULL DEFAULT true,
    "createdById" text,
    "sourceFileName" text,
    "sourceImportId" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."QuestionOption" (
    "id" text NOT NULL,
    "questionId" text NOT NULL,
    "optionKey" text NOT NULL,
    "optionText" text NOT NULL,
    "isCorrect" bool NOT NULL DEFAULT false,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."AssessmentQuestion" (
    "id" text NOT NULL,
    "assessmentId" text NOT NULL,
    "questionId" text NOT NULL,
    "questionOrder" int4 NOT NULL,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."UserBatch" (
    "id" text NOT NULL,
    "fileName" text NOT NULL,
    "batchName" text NOT NULL,
    "totalCandidates" int4 NOT NULL DEFAULT 0,
    "createdById" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."AssessmentAnswer" (
    "id" text NOT NULL,
    "assessmentId" text NOT NULL,
    "questionId" text NOT NULL,
    "selectedOption" text NOT NULL,
    "answeredAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."User" (
    "id" text NOT NULL,
    "name" text NOT NULL,
    "email" text NOT NULL,
    "passwordHash" text NOT NULL,
    "role" "public"."Role" NOT NULL DEFAULT 'USER'::"Role",
    "isActive" bool NOT NULL DEFAULT true,
    "batchId" text,
    "createdById" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL,
    "contactNumber" text,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."ExamControl" (
    "id" text NOT NULL DEFAULT 'global'::text,
    "isExamStarted" bool NOT NULL DEFAULT false,
    "startedAt" timestamp(3),
    "startedById" text,
    "updatedAt" timestamp(3) NOT NULL,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."AwsMarketplaceSubscription" (
    "id" text NOT NULL,
    "customerIdentifier" text,
    "customerAccountId" text,
    "productCode" text NOT NULL,
    "dimension" text,
    "quantity" int4 NOT NULL DEFAULT 1,
    "status" "public"."AwsSubscriptionStatus" NOT NULL DEFAULT 'PENDING_REGISTRATION'::"AwsSubscriptionStatus",
    "expirationDate" timestamp(3),
    "userId" text NOT NULL,
    "activatedAt" timestamp(3),
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "licenseArn" text,
    "agreementId" text,
    PRIMARY KEY ("id")
);

-- Table Definition
CREATE TABLE "public"."AwsMarketplaceEvent" (
    "id" text NOT NULL,
    "customerIdentifier" text NOT NULL,
    "action" text NOT NULL,
    "status" text NOT NULL,
    "rawPayload" text,
    "processed" bool NOT NULL DEFAULT false,
    "processedAt" timestamp(3),
    "error" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "licenseArn" text,
    "agreementId" text,
    "customerAccountId" text,
    "subscriptionId" text,
    "source" text,
    "detailType" text,
    PRIMARY KEY ("id")
);

